={{ (() => {
  const vars = $('Set Variables1').first().json || {};
  const q = vars.search_query || 'Roofers in Solihull, UK';
  let ll = undefined;
  try {
    const geo = $('Geocoding API (Coordinates)1').first().json;
    const item = Array.isArray(geo) ? geo[0] : geo;
    if (item && item.lat && item.lon) {
      ll = '@' + item.lat + ',' + item.lon + ',14z';
    }
  } catch (e) {}
  const payload = { q, gl: 'gb', hl: 'en' };
  if (ll) payload.ll = ll;
  return JSON.stringify(payload);
})() }}

