let rawList = [];
for (const entry of $input.all()) {
  if (entry.json && Array.isArray(entry.json.places)) {
    rawList.push(...entry.json.places);
  } else if (Array.isArray(entry.json)) {
    rawList.push(...entry.json);
  } else if (entry.json && Array.isArray(entry.json.data)) {
    rawList.push(...entry.json.data);
  } else if (entry.json) {
    rawList.push(entry.json);
  }
}

let searchQuery = '';
let location = '';
let onlyNoWebsite = false;
let mobilesOnly = false;
let minReviews = 2;

try {
  const vars = $('Set Variables1').first().json;
  searchQuery = vars.search_query || '';
  location = vars.location || '';
  if (vars.only_no_website !== undefined) onlyNoWebsite = Boolean(vars.only_no_website);
  if (vars.mobiles_only !== undefined) mobilesOnly = Boolean(vars.mobiles_only);
  if (vars.min_reviews !== undefined) minReviews = Number(vars.min_reviews);
} catch (e) {}

function detectTrade(category, query, name) {
  const str = ((category || '') + ' ' + (query || '') + ' ' + (name || '')).toLowerCase();
  if (str.includes('roof')) return 'Roofer';
  if (str.includes('dent') || str.includes('smile') || str.includes('implant')) return 'Dentist';
  if (str.includes('plumb') || str.includes('drain') || str.includes('boiler')) return 'Plumber';
  if (str.includes('electric')) return 'Electrician';
  if (str.includes('account') || str.includes('tax') || str.includes('bookkeep')) return 'Accountant';
  if (str.includes('build') || str.includes('loft') || str.includes('extension')) return 'Builder';
  if (str.includes('landscap') || str.includes('tree') || str.includes('garden')) return 'Landscaper';
  if (str.includes('clean')) return 'Cleaner';
  if (str.includes('carpent') || str.includes('joiner')) return 'Carpenter';
  if (str.includes('paint') || str.includes('decorat')) return 'Decorator';
  return 'Tradesperson';
}

const formattedLeads = [];
const seenPhones = new Set();
const seenNames = new Set();

for (const data of rawList) {
  const businessName = (data.title || data.name || '').trim();
  const rawWebsite = (data.website || '').trim();
  const rawPhone = (data.phoneNumber || data.phone || data.phoneUnformatted || '').trim();
  const totalScore = Number(data.rating || data.totalScore || 0);
  const reviewsCount = Number(data.ratingCount || data.reviewsCount || 0);
  const rawAddress = (data.address || data.city || '').trim();
  const category = (data.type || data.category || data.categoryName || '').trim();

  // Quality Gate 1: Require valid name and contact phone
  if (!businessName || !rawPhone) continue;

  // Quality Gate 2: Eliminate ghost/abandoned listings with 0 or low reviews
  if (reviewsCount < minReviews) continue;

  // Normalize Phone
  let cleanPhone = rawPhone.replace(/[^0-9+]/g, '');
  if (cleanPhone.startsWith('0')) {
    cleanPhone = '+44' + cleanPhone.substring(1);
  }
  if (!cleanPhone.startsWith('+44')) {
    cleanPhone = '+44' + cleanPhone.replace(/^\+/, '');
  }

  // DEDUPLICATION: Skip duplicates in current batch
  const nameKey = businessName.toLowerCase().replace(/[^a-z0-9]/g, '');
  if (seenPhones.has(cleanPhone) || seenNames.has(nameKey)) {
    continue;
  }
  seenPhones.add(cleanPhone);
  seenNames.add(nameKey);

  // Accurate Online Presence Classification
  let classification = 'has_website';
  if (!rawWebsite || rawWebsite === '' || rawWebsite.toLowerCase() === 'none') {
    classification = 'no_website';
  } else {
    const w = rawWebsite.toLowerCase();
    if (
      w.includes('facebook.com') ||
      w.includes('instagram.com') ||
      w.includes('yell.com') ||
      w.includes('checkatrade.com') ||
      w.includes('trustatrader.com') ||
      w.includes('bark.com') ||
      w.includes('mybuilder.com')
    ) {
      classification = 'social_only';
    }
  }

  const hasWebsite = (classification === 'has_website');

  // Strict Filters
  if (onlyNoWebsite && classification !== 'no_website') continue;

  const isMobile = cleanPhone.startsWith('+447');
  if (mobilesOnly && !isMobile) continue;

  const channel = isMobile ? 'WhatsApp / SMS' : 'Landline / Direct Call';
  const waDigits = cleanPhone.replace('+', '');
  const waLink = isMobile ? `https://wa.me/${waDigits}?text=${encodeURIComponent('Hi 👋')}` : 'N/A';

  let address = rawAddress;
  if (!address) {
    address = location || searchQuery.replace(/^Roofers in /i, '').replace(/, UK/i, '') || 'UK Regional';
  }

  const trade = detectTrade(category, searchQuery, businessName);
  const tradeLower = trade.toLowerCase();

  // PREFILLED OUTREACH MESSAGES (Option 2 Local Business Focus)
  const stage1Opener = 'Hi 👋';
  const stage2Pitch = (classification === 'no_website')
    ? `Came across ${businessName} — had a look for a website, couldn't find one. Every day someone searches for a ${tradeLower} near them, sees you're not there, and books with whoever showed up instead. I build the site before I ever ask for money. If it's not for you, no pressure at all.`
    : (classification === 'social_only')
    ? `Came across ${businessName} — saw your social page, noticed you don't have a direct quote intake system. That's where customers drop off to the next listing. I build the storefront and booking system before asking for anything.`
    : `Came across ${businessName} — saw your site, noticed it isn't set up for instant mobile quotes and speed-to-lead. We automate enquiry-to-booked quotes for local trades.`;

  const followUp1 = `Hey — following up on ${businessName}. No pressure at all, just wanted to check if this landed and see where you're at.`;
  const followUpFinal = `Last one from me on this — if it's not a priority right now, that's completely fair. If it ever is, the offer stands, just say the word.`;

  // Safe Supabase payload object
  const supabasePayload = {
    name: "Owner / Director",
    business_name: businessName,
    phone: cleanPhone,
    website: hasWebsite ? rawWebsite : (classification === 'social_only' ? rawWebsite : null),
    service_interested: "Digital Storefront & Speed-to-Lead Automation",
    notes: `${address} · ★${totalScore} (${reviewsCount} reviews)`,
    status: "New",
    source: "google_maps_outreach",
    lead_type: "local",
    local_business_niche: trade,
    outreach_category: classification,
    outreach_stage: "uncontacted",
    whatsapp_direct_url: isMobile ? waLink : null,
    scraped_metadata: {
      address: address,
      rating: totalScore,
      reviews_count: reviewsCount,
      rating_reviews: `${reviewsCount} (★${totalScore})`,
      trade: trade,
      stage_1_opener: stage1Opener,
      stage_2_pitch: stage2Pitch,
      follow_up_1: followUp1,
      follow_up_final: followUpFinal
    }
  };

  formattedLeads.push({
    json: {
      "Business Name": businessName,
      "Phone": cleanPhone,
      "Channel": channel,
      "WhatsApp Link": waLink,
      "Reviews": reviewsCount,
      "Rating": totalScore,
      "Reviews & Rating": `${reviewsCount} (★${totalScore})`,
      "Website": rawWebsite || 'None',
      "Address": address,
      "Trade": trade,
      "Classification": classification,
      "Stage 1 Opener": stage1Opener,
      "Stage 2 Pitch": stage2Pitch,
      "Follow Up 1": followUp1,
      "Follow Up Final": followUpFinal,
      "Status": 'New',
      "supabase_payload": supabasePayload
    }
  });
}

return formattedLeads;
